using FunctionPtr = double(*)(double);

// Helper function to compute the trapezoidal estimate for [x, y]
double trapezoidal_estimate(FunctionPtr f, double x, double y) {
    return (y - x) * (f(x) + f(y)) / 2.0;
}

double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    double m = (a + b) / 2.0;
    double full_estimate = trapezoidal_estimate(f, a, b);
    double left_estimate = trapezoidal_estimate(f, a, m);
    double right_estimate = trapezoidal_estimate(f, m, b);
    double sum_estimates = left_estimate + right_estimate;

    if (std::abs(sum_estimates - full_estimate) <= 15.0 * precision) {
        return sum_estimates + (sum_estimates - full_estimate) / 15.0;
    } else {
        return adaptive_trapezoidal(f, a, m, precision / 2.0) +
               adaptive_trapezoidal(f, m, b, precision / 2.0);
    }
}

double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    double m = (a + b) / 2.0;
    double full_estimate = (b - a) * (f(a) + f(b)) / 2.0;
    double left_estimate = (m - a) * (f(a) + f(m)) / 2.0;
    double right_estimate = (b - m) * (f(m) + f(b)) / 2.0;
    double sum_estimates = left_estimate + right_estimate;

    // Error estimate: |sum_estimates - full_estimate| / 15
    if (std::abs(sum_estimates - full_estimate) <= 15.0 * precision) {
        return sum_estimates + (sum_estimates - full_estimate) / 15.0;
    } else {
        return adaptive_trapezoidal(f, a, m, precision / 2.0) +
               adaptive_trapezoidal(f, m, b, precision / 2.0);
    }
}

double adaptive_trapezoidal(double (*f)(double), double a, double b, double precision) {
    double m = (a + b) / 2.0;
    double full_estimate = (b - a) * (f(a) + f(b)) / 2.0;
    double left_estimate = (m - a) * (f(a) + f(m)) / 2.0;
    double right_estimate = (b - m) * (f(m) + f(b)) / 2.0;
    double sum_estimates = left_estimate + right_estimate;

    if (std::abs(sum_estimates - full_estimate) <= 15.0 * precision) {
        return sum_estimates + (sum_estimates - full_estimate) / 15.0;
    } else {
        return adaptive_trapezoidal(f, a, m, precision / 2.0) +
               adaptive_trapezoidal(f, m, b, precision / 2.0);
    }
}

